engine:
// lane-probe-menu StatusMenu Engine
// Version: the const below is the ONE place it is written, and it is EXPORTED — mvu-helper reads
// it off the running module, and reads this same line when validating a pack that is not loaded.
const ENGINE_VERSION = 'v1.1';
// Purpose: the minimal, honest instance of the SS9.5 exports contract - two formatters and one
// action - so the install lane, the Worker boot, the formatter batch RPC and the patch apply can
// each be proven against code that does nothing clever. Formatters are (stat, root) => string and
// PURE; actions are (args, statSnapshot) => patch[] and NEVER write - mvu-helper applies.
const getV = (obj, path, fallback) => {
  let cur = obj;
  for (const seg of String(path || '').split('.')) {
    if (cur == null || typeof cur !== 'object') return fallback;
    cur = cur[seg];
  }
  if (Array.isArray(cur)) cur = cur[0];
  return cur === undefined ? fallback : cur;
};
module.exports = {
    ENGINE_VERSION,
  actions: {
    // The equip shape from the plan's exit criteria: move an item between two named slots.
    // Returns patches; applying them is mvu-helper's (SS9.4), and the log there enumerates each.
    probeEquip({ itemKey }, stat) {
      const key = String(itemKey || 'ProbeItem');
      const had = getV(stat, 'Mainchar.Inventory.' + key, null);
      return [
        { op: 'delete', path: 'Mainchar.Inventory.' + key },
        { op: 'set', path: 'Mainchar.Equipment.' + key, value: had === null ? 'probe-equipped' : had },
      ];
    },
    // A deliberately malformed emitter for the G3.5 refusal guard: a well-typed action whose
    // SECOND patch has a bad op. The whole action must be refused, naming the offender.
    probeMalformed() {
      return [
        { op: 'set', path: 'Mainchar.ProbeFlag', value: true },
        { op: 'assign', path: 'Mainchar.ProbeFlag2', value: true },
      ];
    },
  },
  formatters: {
    moneyDisplay(stat, root) { return 'Y ' + getV(root, 'Mainchar.Money', '?'); },
    mapVariant(stat, root) { return (Number(getV(root, 'Mainchar.Level', 0)) > 70) ? 'post-70-map' : 'pre-70-map'; },
  },
};
